export const getCarDetails = (draftQuotationsDetailsData) => {
  const details = [
    {
      name: 'Tahun Kendaraan',
      value: draftQuotationsDetailsData?.policy_details?.year,
    },
    {
      name: 'Merek Kendaraan',
      value: draftQuotationsDetailsData?.policy_details?.brand,
    },
    {
      name: 'Model Kendaraan',
      value: draftQuotationsDetailsData?.policy_details?.variant,
    },
    {
      name: 'Harga Kendaraan',
      value: formatMoney(
        draftQuotationsDetailsData?.policy_details?.model_data?.price
      ),
    },
    {
      name: 'Jenis Kendaraan',
      value: draftQuotationsDetailsData?.policy_details?.vehicle_type,
    },
    {
      name: 'Penggunaan',
      value: draftQuotationsDetailsData?.policy_details?.usage,
    },
    {
      name: 'Nomor Rangka',
      value: draftQuotationsDetailsData?.policy_details?.chasis_number,
    },
    {
      name: 'Nomor Mesin',
      value: draftQuotationsDetailsData?.policy_details?.machine_number,
    },
    {
      name: 'Kode Daerah',
      value: draftQuotationsDetailsData?.policy_details?.region_code,
    },
    {
      name: 'Nomor Plat',
      value: draftQuotationsDetailsData?.policy_details?.plate_number,
    },
    {
      name: 'Kode Belakang',
      value: draftQuotationsDetailsData?.policy_details?.back_plate,
    },
  ]

  return details.filter(
    (detail) =>
      detail.value !== undefined && detail.value !== null && detail.value !== ''
  )
}

export const getProductDetails = (draftQuotationsDetailsData) => {
  const yearMap =
    draftQuotationsDetailsData?.policy_details?.year_based_package_type_map ||
    []

  const counts = yearMap.reduce(
    (acc, curr) => {
      if (curr.package_type === 'car-protection-comprehensive')
        acc.comprehensive += 1
      else if (curr.package_type === 'car-protection-tlo') acc.tlo += 1
      return acc
    },
    { comprehensive: 0, tlo: 0 }
  )

  const manfaat = [
    counts.comprehensive ? `${counts.comprehensive} Tahun Komprehensif` : null,
    counts.tlo ? `${counts.tlo} Tahun TLO` : null,
  ]
    .filter(Boolean)
    .join(' + ')

  return [
    {
      name: 'Periode Perlindungan',
      value: `${draftQuotationsDetailsData?.policy_details?.year_based_package_type_map?.length || 0} Tahun`,
    },
    {
      name: 'Manfaat',
      value: manfaat || '',
    },
    {
      name: 'Kategori Asuransi',
      value:
        draftQuotationsDetailsData?.policy_details?.package_data?.package
          ?.product?.name,
    },
    {
      name: 'Nilai Pertanggungan',
      value: formatMoney(
        draftQuotationsDetailsData?.policy_details?.vehicle_sum_insured
      ),
    },
    {
      name: 'Tanggal Mulai Polis',
      value: moment(
        draftQuotationsDetailsData?.policy_details?.start_date
      ).format('DD/MM/YYYY'),
    },
    {
      name: 'Tanggal Berakhir Polis',
      value: moment(
        draftQuotationsDetailsData?.policy_details?.end_date
      ).format('DD/MM/YYYY'),
    },
  ]
}

export const CUSTOMER_NOTE = [
  'Pengajuan via online',
  'Layanan Pelanggan WA (+62) 818 343 494',
  'Apabila terdapat perbedaan data pada penawaran (QS) dengan sertifikat polis (SCP), maka akan mengacu kepada regulasi OJK.',
]

function MVPolicyQsContainer() {
  const { id } = useParams()
  const [{ getDownloadDraftPdfStatus }, dispatchError] = useErrorContextValue()
  const [
    { getCustomerDraftQuoteDetailData = {} },
    getDraftQuoteCustomerDetailsReq,
  ] = useGetCustomerQuoteDetails()
  const [{ getDownloadDraftPdfData = {} }, getDownloadDraftPdfReq] =
    useGetDownloadDraftPdf()
  const dataSource = getCustomerDraftQuoteDetailData

  useEffect(() => {
    if (id) {
      getDraftQuoteCustomerDetailsReq({ draftQuoteId: id })
    }
  }, [getDraftQuoteCustomerDetailsReq, id])

  const renderProfileAgCards = (list, title) => {
    return (
      <>
        <CustomText
          color={AgentColorPallette.ppBlue}
          weight={700}
          size="15px"
          padLeft="16px"
        >
          {title}
        </CustomText>
        <ProfileContentCol>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(2, 1fr)',
              width: '100%',
            }}
          >
            {list.map((item, index) => (
              <ProfileItemStyle border={index + 1 !== list?.length} key={index}>
                <DisplayFlexCCC className="align-items-start">
                  <CustomText
                    textAlign="start"
                    color={AgentColorPallette.fontGrey}
                    weight={400}
                    size="13px"
                    bottom="0"
                    paddingTop={'10px'}
                  >
                    {item.name}
                  </CustomText>
                  <CustomText
                    textAlign="start"
                    color={AgentColorPallette.black}
                    weight={400}
                    size="13px"
                    bottom="0"
                    paddingTop={'5px'}
                  >
                    {item.value}
                  </CustomText>
                </DisplayFlexCCC>
              </ProfileItemStyle>
            ))}
          </div>
        </ProfileContentCol>
      </>
    )
  }

  useEffect(() => {
    if (getDownloadDraftPdfStatus === 'success' && getDownloadDraftPdfData) {
      downloadFile(getDownloadDraftPdfData.pdf_url)
      dispatchError(
        resetError({
          getDownloadDraftPdfStatus: '',
        })
      )
    }
  }, [getDownloadDraftPdfStatus, getDownloadDraftPdfData, dispatchError])

  const handleDownloadPdf = () => {
    if (id) {
      getDownloadDraftPdfReq({
        draftId: id,
      })
    }
  }

  const quoteNumber = dataSource?.id ? `PPMitra-${dataSource?.id}` : ''
  const policyDetails = dataSource?.policy_details
  const packageData = dataSource?.policy_details?.package_data

  return (
    <QsSlipConatiner>
      <MitraHeaderLogo src={QS_LOGO_PP_MV}></MitraHeaderLogo>
      <CardHeaderCtn>
        <ImageCtn>
          {packageData?.provider?.logo_url && (
            <img
              src={packageData?.provider?.logo_url}
              width={48}
              height={20}
              alt="logo"
              lassName="logo-image"
            />
          )}
        </ImageCtn>
        <CustomText
          weight={600}
          size="13px"
          textAlign={'center'}
          marginBottom={'5px'}
          color={AgentColorPallette.fontGrey}
        >
          {packageData?.provider?.name}
        </CustomText>
        <CustomText
          weight={800}
          size="15px"
          textAlign={'center'}
          color={AgentColorPallette.black}
        >
          {'Asuransi Kendaraan'}
        </CustomText>
        <div className="margin">
          <DisplayFlexPP>
            <QuoteId>No. Penawaran</QuoteId>
            <QuoteId>{quoteNumber}</QuoteId>
          </DisplayFlexPP>
        </div>
      </CardHeaderCtn>
      <Hr />
      {renderProfileAgCards(getProductDetails(dataSource), 'Detail Perlindungan')}
      <Hr />
      {renderProfileAgCards(getCarDetails(dataSource), 'Data Kendaraan')}
      <Hr />
      {policyDetails?.ktp_no && (
        <>
          {renderProfileAgCards(getCustomerDetails(dataSource), 'Data Pelanggan')}
          <Hr />
        </>
      )}
      <div className="margin">
        <MVPremiumBreakdown policyDetails={policyDetails} />
      </div>
      <Hr />
      <CustomerNoteStyle>
        <CustomText
          color={AgentColorPallette.black}
          size="15px"
          bottom="4px"
          weight={600}
        >
          {LANG_STRINGS.note}:
        </CustomText>
        {CUSTOMER_NOTE.map((note, index) => (
          <CustomText
            key={`note_${index}`}
            color={AgentColorPallette.black}
            bottom="4px"
            lineHeight={1.5}
            size="13px"
          >
            {`${index + 1}. ${note}`}
          </CustomText>
        ))}
      </CustomerNoteStyle>
      <Hr />
      <Footer>
        <CustomText weight="700" size="9px" textAlign="center" color="#000000">
          {LANG_STRINGS.OjkText}
        </CustomText>
        <img src={OJK_PP_BLACK} className="ojk-logo" alt="logo" />
      </Footer>
      <BtnContainerStyle>
        <Button
          className="select-buttons reject-button"
          onClick={handleDownloadPdf}
        >
          {'Download'}
        </Button>
      </BtnContainerStyle>
    </QsSlipConatiner>
  )
}

export default MVPolicyQsContainer
